contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "insufficient balance");

        bool zeroReverted;
        c.go(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { zeroReverted = true; } else { zeroReverted = false; }

        bool fundedReverted;
        c.go{value: amount}(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { fundedReverted = true; } else { fundedReverted = false; }

        assert(zeroReverted || !fundedReverted);
    }

    receive() external payable {}
}

